95	      throw std::runtime_error("ResumeDriver::resume: bad magic");
96	    if (state.version != HYBRID_STATE_VERSION)
97	      throw std::runtime_error("ResumeDriver::resume: unsupported version");
98	    // L6: only U(0)/S(1)/M(3) fit dcsr.prv; 2 is the reserved encoding.
99	    if (state.priv == 2 || state.priv > 3)
100	      throw std::runtime_error("ResumeDriver::resume: invalid privilege");
101	
102	    // dmactive must transition 0->1 in its own write before any other
103	    // DMCONTROL bit is honored (RISC-V Debug Spec).
104	    bus_.write(kDmcontrol, kDmcontrolDmactive);
105	    request_halt();
106	    poll_until_set(bus_, kDmstatus, kDmstatusAllhalted, "ResumeDriver halt");
107	
108	    // mstatus: enable FS / VS so the following FPR / V abstract writes are
109	    // accepted (FS or VS == Off disables the extension and the hart NACKs
110	    // the writes). The drained state.mstatus may legitimately carry FS or
111	    // VS at Off (e.g. an OS context-switched the regs away before the
112	    // trigger fired) -- gating the write on the drained field skips the
113	    // enable and silently NACKs every subsequent FPR / V-CSR write. Always
114	    // write mstatus when either extension is in scope; force-OR Initial
115	    // when the drained field is Off. This enable is local to the vsim
116	    // phase; the state.mstatus written to the handoff file is left
117	    // unmodified.
118	    if (state.flags & (HYBRID_FLAG_FP | HYBRID_FLAG_V)) {
119	      uint64_t enable_mstatus = state.mstatus;
120	      if ((state.flags & HYBRID_FLAG_FP) && (enable_mstatus & kMstatusFsMask) == 0)
121	        enable_mstatus |= kMstatusFsInitial;  // FS = Initial
122	      if ((state.flags & HYBRID_FLAG_V)  && (enable_mstatus & kMstatusVsMask) == 0)
123	        enable_mstatus |= kMstatusVsInitial;  // VS = Initial
124	      write_csr_abstract_or_pb(kCsrMstatus, enable_mstatus);
125	    }
126	
127	    // FPR restore (requires mstatus.FS enabled above): one abstract register
128	    // write per f-reg. Abstract-only by design, like every non-V register
129	    // block -- the Program Buffer is reserved for state the abstract command
130	    // space cannot reach (the V regfile, vtype/vl, L2C MMIO).
131	    if (state.flags & HYBRID_FLAG_FP) {
132	      for (uint16_t i = 0; i < 32; ++i)
133	        write_64bit_register(regno_fpr(i), state.fpr[i]);
134	      // L20: fcsr (frm + sticky fflags). Same FS gate as the FPRs; PB
135	      // fallback scratch x5 is overwritten by the GPR loop below.
136	      write_csr_abstract_or_pb(kCsrFcsr, state.fcsr);
137	    }
