159	      write_64bit_register(regno_gpr(6), state.vtype);
160	      const std::array<uint32_t, 1> pb_vsetvl = { encode_vsetvl(0, 5, 6) };
161	      exec_progbuf(bus_, std::span<const uint32_t>{pb_vsetvl});
162	      // vstart must come AFTER vsetvl: vsetvl resets vstart to 0.
163	      write_csr_abstract_or_pb(kCsrVstart, state.vstart);
164	      write_csr_abstract_or_pb(kCsrVxsat,  state.vxsat);
