204	  // Enables the vsim->QEMU handoff drain. After this is set, run() watches
205	  // committed PCs and on retire of the `slti x0, x0, 0x5A1` exit marker drains
206	  // architectural state to `state_out_path` and returns kExitHandoffToQemu.
207	  //
208	  // When `exit_pc` is set, the trigger is populated by `add_pc_hit` (PC
209	  // mode) and the ELF scan is skipped: the binary need not contain a marker
210	  // HINT. Marker mode and PC mode are mutually exclusive on a single run --
211	  // callers pass exactly one form.
212	  void enable_hybrid_handoff(const std::string& elf_path,
213	                             const std::string& state_out_path,
214	                             std::optional<uint64_t> exit_pc = std::nullopt)
215	  {
216	    hybrid::CsrTrigger trigger;
217	    if (exit_pc) {
218	      trigger.add_pc_hit(*exit_pc, HYBRID_HANDOFF_EXIT);
219	      spdlog::info("hybrid: PC-trigger mode, exit_pc=0x{:x}", *exit_pc);
220	    } else {
221	      auto elf = LIEF::ELF::Parser::parse(elf_path);
222	      if (!elf)
223	        throw std::runtime_error(
224	          "enable_hybrid_handoff: failed to parse " + elf_path);
225	      for (const auto& seg: elf->segments()) {
226	        if (seg.type() != LIEF::ELF::SEGMENT_TYPES::PT_LOAD) continue;
227	        if ((static_cast<unsigned>(seg.flags()) & 1u) == 0u) continue;  // PF_X
228	        const auto content = seg.content();
229	        const std::span<const uint8_t> bytes{content.data(), content.size()};
230	        trigger.scan_buffer(bytes, seg.virtual_address());
231	      }
232	    }
233	
234	    hybrid_dmi_bus_ = std::make_unique<
235	      hybrid::SystemCDmiBus<PLATFORM::dmi_addr_width,
236	                            PLATFORM::dmi_data_width>>(platform.dmi,
237	                                                       platform.clk.period());
238	    hybrid_handoff_.emplace(std::move(trigger), *hybrid_dmi_bus_);
239	    if (hybrid_input_state_)
240	      hybrid_handoff_->set_passthrough_input(*hybrid_input_state_);
241	    hybrid_state_path_ = state_out_path;
242	  }
