// Andes-CSR capability gating.
//
// A core implements an Andes custom CSR only when the matching feature is
// configured into it (config.inc). Restoring a CSR the target core lacks can
// hang the DMI handshake -- observed on ax45mpv_premium for ucode (no DSP). So
// the resume/drain loops transport only the CSRs the target core supports,
// decided here from the core's feature gates.
//
// This header is Verilator/SystemC-free: it maps a CSR address to its gate and
// answers "does a core with these gates support this CSR". The binding of each
// gate to the core's compiled-in `_NDS_*` config macros lives in the sim binary
// (see andes_caps_from_config), so this stays unit-testable in isolation.
//
// Minimal slice: only the DSP -> ucode class is gated here; every other Andes
// CSR is ALWAYS (present on every core). The full v3 gate table, the PMA/M-ext
// gates, and supported_andes_csr_names arrive at their later commits.
#ifndef ANDES_HYBRID_ANDES_CAPS_HPP
#define ANDES_HYBRID_ANDES_CAPS_HPP

#include <cstdint>

namespace hybrid {

// The hardware feature that gates each transported CSR. ALWAYS = unconditionally
// present (a base machine CSR every core has; never gated off). More gate
// classes join this enum as the gate table grows.
enum class AndesGate : uint8_t {
  ALWAYS = 0,
  DSP,          // ucode (DSP overflow flag)
};

// Map an Andes CSR (by address) to the feature gate that enables it. A CSR with
// no custom-extension gate is ALWAYS (a base machine CSR every Andes core has).
// Maintainer note: a CSR that needs gating gets a case here, else it defaults
// to ALWAYS (transported unconditionally).
constexpr AndesGate andes_gate_for(uint16_t csr_addr)
{
  switch (csr_addr) {
    case 0x801: return AndesGate::DSP;           // ucode (DSP overflow flag)
    default:    return AndesGate::ALWAYS;
  }
}

// The set of Andes feature gates a target core has on. Built from the core's
// compiled-in config (config.inc) in the sim binary and injected into the
// resume/drain loops, so they transport only the CSRs the core implements.
// Default = every gate on (all(): no gating, the prior unconditional behavior).
struct AndesCaps {
  uint32_t gate_mask = ~0u;

  static constexpr AndesCaps all()  { return AndesCaps{~0u}; }
  static constexpr AndesCaps none() { return AndesCaps{0u}; }

  constexpr void set(AndesGate g, bool on = true)
  {
    const uint32_t bit = 1u << static_cast<unsigned>(g);
    if (on) gate_mask |= bit;
    else    gate_mask &= ~bit;
  }

  constexpr bool gate_on(AndesGate g) const
  {
    return (gate_mask >> static_cast<unsigned>(g)) & 1u;
  }

  // ALWAYS-gated CSRs are present on every core regardless of the mask.
  constexpr bool supports_csr(uint16_t csr_addr) const
  {
    const AndesGate g = andes_gate_for(csr_addr);
    return g == AndesGate::ALWAYS || gate_on(g);
  }
};

}  // namespace hybrid

#endif  // ANDES_HYBRID_ANDES_CAPS_HPP

// Build an AndesCaps from the core's compiled-in config.inc feature macros
// (_NDS_*, supplied by the build-generated cpu_config.hpp). This is the ONE
// place that binds each Andes feature gate to its config macro -- the sim-binary
// counterpart of the Verilator-free andes_caps.hpp, kept separate so the unit
// tests never need the generated header.
//
// PRECONDITION: the _NDS_* macros must already be in scope (include this AFTER
// cpu_config.hpp). A macro that is absent reads as "feature off" (gate clear),
// never a compile error -- so a core whose config omits a knob stays safe.
//
// Minimal slice: only the DSP gate is bound; the remaining gates join as the
// gate table grows.
#pragma once

#include "hybrid/andes_caps.hpp"

namespace hybrid {

inline AndesCaps andes_caps_from_config()
{
  AndesCaps c = AndesCaps::none();

#if defined(_NDS_DSP_SUPPORT_INT) && _NDS_DSP_SUPPORT_INT
  c.set(AndesGate::DSP);           // ucode
#endif

  return c;
}

}  // namespace hybrid

// Andes-CSR capability gating (prototype slice). A core implements an Andes
// custom CSR only when its config.inc enables the matching feature; restoring a
// CSR the core lacks can hang the DMI handshake (observed on ax45mpv_premium:
// ucode). So the resume/drain loops transport only the CSRs the target core
// supports. This minimal slice pins ONE gate class end-to-end: DSP -> ucode
// (0x801). Every other Andes CSR is ALWAYS (present on every core) until the
// full gate table lands.
#define DOCTEST_CONFIG_IMPLEMENT_WITH_MAIN
#include "doctest.h"

#include "hybrid/andes_caps.hpp"

using hybrid::AndesCaps;
using hybrid::AndesGate;

TEST_CASE("andes_gate_for maps ucode (0x801) to DSP; everything else is ALWAYS")
{
  CHECK(hybrid::andes_gate_for(0x801) == AndesGate::DSP);     // ucode
  CHECK(hybrid::andes_gate_for(0x800) == AndesGate::ALWAYS);  // uitb
  CHECK(hybrid::andes_gate_for(0x7C4) == AndesGate::ALWAYS);  // mxstatus
}

TEST_CASE("all() transports every Andes CSR (default = no gating)")
{
  const AndesCaps c = AndesCaps::all();
  CHECK(c.supports_csr(0x801));  // ucode    (DSP)
  CHECK(c.supports_csr(0x800));  // uitb     (ALWAYS)
  CHECK(c.supports_csr(0x7C4));  // mxstatus (ALWAYS)
}

TEST_CASE("a core without DSP skips ucode (the hang case) but keeps the ALWAYS CSRs")
{
  const AndesCaps c = AndesCaps::none();  // DSP off; ALWAYS still on
  CHECK_FALSE(c.supports_csr(0x801));     // ucode -- absent, must not be touched
  CHECK(c.supports_csr(0x800));           // uitb     (ALWAYS)
  CHECK(c.supports_csr(0x7C4));           // mxstatus (ALWAYS)
}

TEST_CASE("set/gate_on toggles a single gate")
{
  AndesCaps c = AndesCaps::none();
  CHECK_FALSE(c.gate_on(AndesGate::DSP));
  c.set(AndesGate::DSP);
  CHECK(c.gate_on(AndesGate::DSP));
  CHECK(c.supports_csr(0x801));           // ucode now supported
  c.set(AndesGate::DSP, false);
  CHECK_FALSE(c.gate_on(AndesGate::DSP));
  CHECK_FALSE(c.supports_csr(0x801));
}

// Tests the config.inc-macro -> AndesCaps binding (andes_caps_from_config),
// prototype slice: only the DSP gate is bound. The real _NDS_* macros come from
// the build-generated cpu_config.hpp; here we define one ourselves so the #if
// mapping is unit-tested with a controlled input and no Verilator build is
// needed.
#define _NDS_DSP_SUPPORT_INT 1

#define DOCTEST_CONFIG_IMPLEMENT_WITH_MAIN
#include "doctest.h"

#include "hybrid/andes_caps_config.hpp"

using hybrid::AndesGate;

TEST_CASE("_NDS_DSP_SUPPORT_INT=1 -> DSP gate on -> ucode transported")
{
  const auto c = hybrid::andes_caps_from_config();
  CHECK(c.gate_on(AndesGate::DSP));
  CHECK(c.supports_csr(0x801));  // ucode    (DSP on)
  CHECK(c.supports_csr(0x7C4));  // mxstatus (always)
}

